import json
from collections import Counter

# Let me verify my transform one more time to make sure
def transform(grid):
    colors = set()
    for row in grid:
        for cell in row:
            colors.add(cell)

    if len(colors) <= 1:
        return grid

    color_counts = Counter()
    for row in grid:
        for cell in row:
            color_counts[cell] += 1

    sorted_colors = sorted(color_counts.keys(), key=lambda x: color_counts[x])
    minority = sorted_colors[0]
    majority = sorted_colors[-1]

    if minority < majority:
        destroy = minority
        survival_color = majority
    else:
        destroy = majority
        survival_color = minority

    result = []
    for row in grid:
        new_row = []
        for cell in row:
            if cell == destroy:
                new_row.append(0)
            elif cell == survival_color:
                new_row.append(destroy)
            else:
                new_row.append(cell)
        result.append(new_row)
    return result

# Verify on demo pairs
with open('/home/ubuntu/runs/paper/qwen-hpl-u1-turns/play/users/u000/system/state/workspace/programs/task-d2e27133.json') as f:
    demos = json.load(f)

for i, demo in enumerate(demos):
    pred = transform(demo['input'])
    print(f"Demo {i}: {'PASS' if pred == demo['output'] else 'FAIL'}")

